    "faq": {
      "eyebrow": "Common questions",
      "title": "Frequently asked questions",
      "q1": "What is the Malaysia My Second Home (MM2H) programme?",
      "a1": "MM2H is a long-term residency programme run by the Malaysian government that allows foreign nationals to live in Malaysia on a renewable pass, with terms ranging from 5 to 20 years depending on category. It suits retirees, families, investors, and remote professionals looking for a second home in Southeast Asia.",
      "q2": "Who is eligible to apply for MM2H?",
      "a2": "Eligibility depends on your chosen category. Platinum, Gold, and Silver require a minimum principal applicant age of 25; the SEZ/SFZ categories require a minimum age of 21. All applicants must also show proof of the required fixed deposit and meet the income and property requirements set by the One Stop Centre MM2H.",
      "q3": "Can I include my family in my application?",
      "a3": "Yes. A legal spouse, unmarried children up to age 35, and parents or parents-in-law can be included as dependents on the same application, subject to the applicable processing fee per dependent.",
      "q4": "How long is the MM2H visa valid for?",
      "a4": "Validity depends on category: Platinum is 20 years, Gold is 15 years, Silver is 5 years, and both SEZ/SFZ tiers are 10 years. All terms are renewable, subject to continued compliance with programme conditions.",
      "q5": "What are the financial requirements to apply?",
      "a5": "Each category requires a fixed deposit placed in a Malaysian bank: USD 1,000,000 for Platinum, USD 500,000 for Gold, USD 150,000 for Silver, and USD 65,000 or USD 32,000 for SEZ/SFZ depending on age. Platinum, Gold, and Silver also require a compulsory residential property purchase at or above a set minimum price.",
      "q6": "Can MM2H visa holders buy property in Malaysia?",
      "a6": "Yes. Platinum, Gold, and Silver categories require a compulsory residential property purchase at or above the minimum price set for that category. SEZ/SFZ categories follow the minimum price set for the relevant Special Economic Zone development.",
      "q7": "Is foreign income taxed once I hold MM2H status?",
      "a7": "Foreign-sourced funds, income, and profit earned on your MM2H fixed deposit are exempt from Malaysian tax under current programme rules. Malaysian-sourced income may still be taxable depending on your circumstances.",
      "q8": "What documents are required to apply?",
      "a8": "Typical requirements include a valid passport, proof of income or savings, a medical examination report, a police clearance certificate, passport-sized photographs, and — where dependents are included — marriage and birth certificates. Exact requirements vary by nationality and category, and all documents must be properly translated and certified where required.",
      "q9": "How long does the MM2H application process take?",
      "a9": "Processing times vary by category and how quickly documents and financial requirements are completed, but applicants typically move through initial submission, in-principle approval, deposit placement, and final visa issuance across several months. Working with an experienced advisor helps avoid delays caused by incomplete documentation.",
      "q10": "Do I need to stay in Malaysia full-time with MM2H?",
      "a10": "No. Platinum, Gold, and Silver categories require a minimum stay of 90 days per year only if the principal applicant is under 50; there is no minimum stay requirement for those aged 50 and above. SEZ/SFZ categories follow the same age-based structure."
    },
