        "notesItem1": "All document copies must be certified by an Embassy, High Commission, or Notary Public and a registered Commissioner for Oaths in Malaysia.",
        "notesItem2": "If the original documents are not in English, they must be translated by a qualified professional translator and officially certified.",
        "processTitle": "MM2H application process",
        "phaseGroup1": "Application submission",
        "phaseGroup2": "Government approval",
        "phaseGroup3": "Visa & arrival",
        "step1Title": "Initial consultation",
        "step1Text": "Consult on MM2H programme details and application procedures, then select the package that best fits your requirements.",
        "step2Title": "Agreement signing & payment",
        "step2Text": "Sign the agency authorization agreement and settle the 20% deposit along with the participation fee.",
        "step3Title": "Document preparation & legalization",
        "step3Text": "Gather and prepare all required application documents, including passports, financial proof, certificate of good conduct, and proof of family relationships.",
        "step4Title": "Document submission for review",
        "step4Text": "All compiled documents are formally submitted to the Ministry of Tourism, Arts and Culture (MOTAC) Malaysia for approval.",
        "step5Title": "Conditional approval issued",
        "step5Text": "Once the MM2H Conditional Approval Letter is granted, you prepare for visa endorsement requirements and settle the remaining balance ahead of travel to Malaysia.",
        "step6Title": "Travel preparation for Malaysia",
        "step6Text": "Enter Malaysia within 3 months from the issuance date of the Conditional Approval Letter to complete visa endorsement / stamping.",
        "step7Title": "Arrival in Malaysia",
        "step7Text": "Present the Approval Letter to open a local bank account, place the required fixed deposit, undergo the medical examination, and purchase medical insurance.",
        "step8Title": "Completion",
        "step8Text": "Successfully collect and endorse your MM2H pass / visa.",
