    "faq": {
      "eyebrow": "常见问题",
      "title": "常见问题解答",
      "q1": "什么是马来西亚第二家园计划(MM2H)?",
      "a1": "MM2H是马来西亚政府推出的长期居留计划,允许外国籍人士凭可续签的居留证在马来西亚居住,期限根据类别从5年到20年不等。该计划适合希望在东南亚拥有第二个家的退休人士、家庭、投资者以及远程办公专业人士。",
      "q2": "谁有资格申请MM2H?",
      "a2": "申请资格取决于您所选择的类别。白金、黄金及白银类别要求主申请人年满25岁;SEZ／SFZ类别则要求年满21岁。所有申请人还须提供所需定期存款证明,并符合MM2H一站式中心规定的收入及房产要求。",
      "q3": "我可以将家人纳入申请吗?",
      "a3": "可以。合法配偶、35岁以下未婚子女,以及父母或配偶的父母均可作为随行家属纳入同一份申请,惟每位随行家属须缴付相应的手续费。",
      "q4": "MM2H签证的有效期是多久?",
      "a4": "有效期依类别而定:白金为20年,黄金为15年,白银为5年,SEZ／SFZ两个级别均为10年。所有期限均可续签,惟须持续符合计划相关条件。",
      "q5": "申请所需的财务条件是什么?",
      "a5": "各类别均须在马来西亚银行存入定期存款:白金为USD 1,000,000,黄金为USD 500,000,白银为USD 150,000,SEZ／SFZ则依年龄为USD 65,000或USD 32,000。白金、黄金及白银类别还须购置达到规定最低价格的住宅房产。",
      "q6": "MM2H签证持有人可以在马来西亚购买房产吗?",
      "a6": "可以。白金、黄金及白银类别均须购置达到该类别规定最低价格的住宅房产。SEZ／SFZ类别则依据相关经济特区项目所设定的最低价格执行。",
      "q7": "持有MM2H身份后,境外收入是否需要纳税?",
      "a7": "根据现行计划规定,来自境外的资金、收入以及MM2H定期存款所产生的利润均可免缴马来西亚税款。惟来自马来西亚本地的收入,视个人情况可能仍须纳税。",
      "q8": "申请需要准备哪些文件?",
      "a8": "一般所需文件包括有效护照、收入或储蓄证明、体检报告、良好品行证明、护照照片,若申请包含随行家属,还须提供结婚证书及出生证明。具体要求因国籍及类别而异,所有文件如有需要均须妥善翻译及认证。",
      "q9": "MM2H申请流程需要多长时间?",
      "a9": "处理时间因类别及文件与财务条件完成速度而异,申请人通常需经历初步提交、原则性批准、存款存入及最终签证签发等阶段,整体约需数月时间。与经验丰富的顾问合作,有助于避免因文件不齐而造成的延误。",
      "q10": "持有MM2H签证是否需要全年居住在马来西亚?",
      "a10": "不需要。白金、黄金及白银类别仅在主申请人未满50岁时,才要求每年至少居住90天;年满50岁者则无最低居住天数要求。SEZ／SFZ类别采用相同的年龄制度。"
    },
