      "a1": "MM2H គឺជាកម្មវិធីស្នាក់នៅរយៈពេលវែងរបស់រដ្ឋាភិបាលម៉ាឡេស៊ី ដែលអនុញ្ញាតឱ្យជនបរទេសរស់នៅម៉ាឡេស៊ីជាមួយប័ណ្ណដែលអាចបន្តបាន ដោយរយៈពេលចាប់ពី 5 ដល់ 20 ឆ្នាំ អាស្រ័យលើប្រភេទ។ វាសមស្របសម្រាប់អ្នកចូលនិវត្តន៍ គ្រួសារ វិនិយោគិន និងអ្នកជំនាញធ្វើការពីចម្ងាយដែលស្វែងរកផ្ទះទីពីរនៅអាស៊ីអាគ្នេយ៍។",
