      "title": "ភ្នាក់ងារដៃគូដែលទទួលបានការអនុញ្ញាតជាផ្លូវការនៅម៉ាឡេស៊ី",
      "intro": "នៅ DCMS MM2H យើងខ្ញុំជួយគ្រួសារ អ្នកចូលនិវត្តន៍ វិនិយោគិន និងអ្នកជំនាញ ឱ្យផ្លាស់ទីលំនៅមកម៉ាឡេស៊ីដោយជោគជ័យតាមរយៈកម្មវិធី Malaysia My Second Home (MM2H)។ ក្នុងនាមជាក្រុមហ៊ុនប្រឹក្សា MM2H ម៉ាឡេស៊ីដែលគួរឱ្យទុកចិត្ត យើងខ្ញុំធ្វើឱ្យនីតិវិធីដាក់ពាក្យសុំដ៏ស្មុគស្មាញ លក្ខខណ្ឌស្នាក់នៅ ការសម្រេចចិត្តអចលនទ្រព្យ និងការរៀបចំផែនការផ្លាស់ទីលំនៅមានភាពសាមញ្ញ ធ្វើឱ្យការផ្លាស់ប្ដូររបស់អ្នកទៅកាន់ម៉ាឡេស៊ីរលូន សុវត្ថិភាព និងគ្មានភាពតានតឹង។",
      "storyEyebrow": "វិធីសាស្ត្ររបស់យើង",
