      "storyP1": "ក្នុងនាមជាទីប្រឹក្សា Malaysia My Second Home (MM2H) ឈានមុខគេ យើងខ្ញុំជួយអតិថិជនធ្វើដំណើរឆ្លងកាត់កម្មវិធីស្នាក់នៅម៉ាឡេស៊ីដែលពេញនិយមបំផុតមួយនៅអាស៊ី ដោយទំនុកចិត្ត និងភាពងាយស្រួល។ មិនថាអ្នកកំពុងស្វែងរករបៀបរស់នៅកាន់តែប្រសើរ ឱកាសចូលនិវត្តន៍ ការអប់រំគុណភាពសម្រាប់កូនរបស់អ្នក ឱកាសវិនិយោគ ឬការស្នាក់នៅរយៈពេលវែងក៏ដោយ ក្រុមការងារមានបទពិសោធន៍របស់យើងផ្តល់ការគាំទ្រពេញលេញពេញមួយដំណើររបស់អ្នកទៅកាន់ My Second Home Malaysia។",
