      "storyP1": "ในฐานะที่ปรึกษา Malaysia My Second Home (MM2H) ชั้นนำ เราช่วยลูกค้าก้าวผ่านหนึ่งในโครงการพำนักที่ได้รับความนิยมมากที่สุดในเอเชียด้วยความมั่นใจและง่ายดาย ไม่ว่าคุณกำลังมองหาไลฟ์สไตล์ที่ดีขึ้น โอกาสในการเกษียณอายุ การศึกษาที่มีคุณภาพสำหรับบุตรหลานของคุณ โอกาสในการลงทุน หรือการพำนักระยะยาว ทีมงานที่มีประสบการณ์ของเราให้การสนับสนุนแบบครบวงจรตลอดการเดินทางสู่ My Second Home Malaysia ของคุณ",
