    "faq": {
      "eyebrow": "Pertanyaan umum",
      "title": "Pertanyaan yang sering diajukan",
      "q1": "Apa itu program Malaysia My Second Home (MM2H)?",
      "a1": "MM2H adalah program tempat tinggal jangka panjang yang dikelola pemerintah Malaysia, yang memungkinkan warga negara asing tinggal di Malaysia dengan izin yang dapat diperpanjang, dengan masa berlaku 5 hingga 20 tahun tergantung kategori. Program ini cocok untuk pensiunan, keluarga, investor, dan profesional yang bekerja jarak jauh yang mencari rumah kedua di Asia Tenggara.",
      "q2": "Siapa yang berhak mengajukan MM2H?",
      "a2": "Kelayakan tergantung pada kategori yang Anda pilih. Platinum, Gold, dan Silver mengharuskan pemohon utama berusia minimal 25 tahun; kategori SEZ/SFZ mengharuskan usia minimal 21 tahun. Semua pemohon juga harus menunjukkan bukti deposito tetap yang diperlukan dan memenuhi persyaratan pendapatan serta properti yang ditetapkan oleh One Stop Centre MM2H.",
      "q3": "Bisakah saya menyertakan keluarga dalam permohonan saya?",
      "a3": "Ya. Pasangan sah, anak yang belum menikah hingga usia 35 tahun, dan orang tua atau mertua dapat disertakan sebagai tanggungan dalam permohonan yang sama, dengan biaya pemrosesan yang berlaku untuk setiap tanggungan.",
      "q4": "Berapa lama masa berlaku visa MM2H?",
      "a4": "Masa berlaku tergantung kategori: Platinum 20 tahun, Gold 15 tahun, Silver 5 tahun, dan kedua tingkat SEZ/SFZ masing-masing 10 tahun. Semua masa berlaku dapat diperpanjang, tergantung pada kepatuhan berkelanjutan terhadap ketentuan program.",
      "q5": "Apa saja persyaratan keuangan untuk mengajukan permohonan?",
      "a5": "Setiap kategori mengharuskan deposito tetap di bank Malaysia: USD 1.000.000 untuk Platinum, USD 500.000 untuk Gold, USD 150.000 untuk Silver, dan USD 65.000 atau USD 32.000 untuk SEZ/SFZ tergantung usia. Platinum, Gold, dan Silver juga mengharuskan pembelian properti hunian wajib pada atau di atas harga minimum yang ditetapkan.",
      "q6": "Bisakah pemegang visa MM2H membeli properti di Malaysia?",
      "a6": "Ya. Kategori Platinum, Gold, dan Silver mengharuskan pembelian properti hunian wajib pada atau di atas harga minimum yang ditetapkan untuk kategori tersebut. Kategori SEZ/SFZ mengikuti harga minimum yang ditetapkan untuk pengembangan Zona Ekonomi Khusus terkait.",
      "q7": "Apakah pendapatan luar negeri dikenakan pajak setelah saya memegang status MM2H?",
      "a7": "Dana, pendapatan, dan keuntungan yang bersumber dari luar negeri yang diperoleh dari deposito tetap MM2H Anda dibebaskan dari pajak Malaysia berdasarkan aturan program saat ini. Pendapatan yang bersumber dari Malaysia mungkin masih dikenakan pajak tergantung pada keadaan Anda.",
      "q8": "Dokumen apa saja yang diperlukan untuk mengajukan permohonan?",
      "a8": "Persyaratan umum meliputi paspor yang masih berlaku, bukti pendapatan atau tabungan, laporan pemeriksaan medis, surat keterangan catatan kepolisian, foto ukuran paspor, dan — jika menyertakan tanggungan — akta nikah dan akta kelahiran. Persyaratan pastinya bervariasi menurut kewarganegaraan dan kategori, dan semua dokumen harus diterjemahkan serta disahkan dengan benar sesuai keperluan.",
      "q9": "Berapa lama proses permohonan MM2H berlangsung?",
      "a9": "Waktu pemrosesan bervariasi menurut kategori dan seberapa cepat dokumen serta persyaratan keuangan diselesaikan, namun pemohon umumnya melalui tahap pengajuan awal, persetujuan prinsip, penempatan deposito, dan penerbitan visa akhir dalam beberapa bulan. Bekerja sama dengan penasihat berpengalaman membantu menghindari keterlambatan akibat dokumen yang tidak lengkap.",
      "q10": "Apakah saya perlu tinggal penuh waktu di Malaysia dengan MM2H?",
      "a10": "Tidak. Kategori Platinum, Gold, dan Silver mengharuskan masa tinggal minimum 90 hari per tahun hanya jika pemohon utama berusia di bawah 50 tahun; tidak ada persyaratan masa tinggal minimum bagi yang berusia 50 tahun ke atas. Kategori SEZ/SFZ mengikuti struktur berbasis usia yang sama."
    },
