    "faq": {
      "eyebrow": "일반적인 질문",
      "title": "자주 묻는 질문",
      "q1": "말레이시아 마이 세컨드 홈(MM2H) 프로그램이란 무엇인가요?",
      "a1": "MM2H는 말레이시아 정부가 운영하는 장기 거주 프로그램으로, 외국인이 갱신 가능한 비자로 말레이시아에 거주할 수 있도록 하며 카테고리에 따라 5년에서 20년까지 유효기간이 다릅니다. 은퇴자, 가족, 투자자, 원격 근무 전문가 등 동남아시아에서 두 번째 집을 찾는 분들에게 적합합니다.",
      "q2": "MM2H를 신청할 자격은 누구에게 있나요?",
      "a2": "자격 요건은 선택한 카테고리에 따라 다릅니다. 플래티넘, 골드, 실버는 주 신청자의 최소 연령이 25세여야 하며, SEZ/SFZ 카테고리는 최소 21세여야 합니다. 모든 신청자는 필요한 정기 예치금 증빙을 제시하고 One Stop Centre MM2H가 정한 소득 및 부동산 요건을 충족해야 합니다.",
      "q3": "신청서에 가족을 포함할 수 있나요?",
      "a3": "네. 법적 배우자, 35세 이하의 미혼 자녀, 부모 또는 배우자의 부모는 동일한 신청서에 부양가족으로 포함될 수 있으며, 부양가족 1인당 해당 수수료가 적용됩니다.",
      "q4": "MM2H 비자의 유효기간은 얼마인가요?",
      "a4": "유효기간은 카테고리에 따라 다릅니다: 플래티넘 20년, 골드 15년, 실버 5년, SEZ/SFZ 두 등급 모두 10년입니다. 모든 기간은 프로그램 조건을 계속 준수하는 한 갱신 가능합니다.",
      "q5": "신청에 필요한 재정 요건은 무엇인가요?",
      "a5": "각 카테고리는 말레이시아 은행에 정기 예치금을 요구합니다: 플래티넘 USD 1,000,000, 골드 USD 500,000, 실버 USD 150,000, SEZ/SFZ는 연령에 따라 USD 65,000 또는 USD 32,000입니다. 플래티넘, 골드, 실버는 또한 정해진 최소 가격 이상의 주거용 부동산 의무 구매가 필요합니다.",
      "q6": "MM2H 비자 소지자는 말레이시아에서 부동산을 구매할 수 있나요?",
      "a6": "네. 플래티넘, 골드, 실버 카테고리는 해당 카테고리에 정해진 최소 가격 이상의 주거용 부동산 의무 구매가 필요합니다. SEZ/SFZ 카테고리는 해당 경제특구 개발 프로젝트에서 정한 최소 가격을 따릅니다.",
      "q7": "MM2H 자격을 취득하면 해외 소득에 세금이 부과되나요?",
      "a7": "현행 프로그램 규정에 따라 MM2H 정기 예치금에서 발생하는 해외 원천 자금, 소득 및 이익은 말레이시아 세금이 면제됩니다. 말레이시아 원천 소득은 개인 상황에 따라 여전히 과세될 수 있습니다.",
      "q8": "신청에 필요한 서류는 무엇인가요?",
      "a8": "일반적인 요건에는 유효한 여권, 소득 또는 저축 증빙, 건강검진 보고서, 무범죄 증명서, 여권 사진, 그리고 부양가족이 포함된 경우 혼인증명서와 출생증명서가 포함됩니다. 정확한 요건은 국적과 카테고리에 따라 다르며, 모든 서류는 필요에 따라 적절히 번역 및 공증되어야 합니다.",
      "q9": "MM2H 신청 절차는 얼마나 걸리나요?",
      "a9": "처리 기간은 카테고리와 서류 및 재정 요건의 완료 속도에 따라 다르지만, 신청자는 일반적으로 최초 제출, 원칙적 승인, 예치금 예치, 최종 비자 발급 단계를 거쳐 몇 개월이 소요됩니다. 경험 많은 상담사와 함께 진행하면 서류 미비로 인한 지연을 피하는 데 도움이 됩니다.",
      "q10": "MM2H로 말레이시아에 항상 거주해야 하나요?",
      "a10": "아닙니다. 플래티넘, 골드, 실버 카테고리는 주 신청자가 50세 미만인 경우에만 연 최소 90일 체류가 필요합니다. 50세 이상은 최소 체류 요건이 없습니다. SEZ/SFZ 카테고리도 동일한 연령 기준 구조를 따릅니다."
    },
