      "intro": "DCMS MM2H는 말레이시아 마이 세컨드 홈(MM2H) 프로그램을 통해 가족, 은퇴자, 투자자 및 전문직 종사자가 성공적으로 말레이시아로 이주할 수 있도록 돕습니다. 신뢰할 수 있는 MM2H 말레이시아 컨설팅 회사로서, 복잡한 신청 절차, 거주 요건, 부동산 결정 및 이주 계획을 간소화하여 말레이시아로의 전환을 원활하고 안전하며 스트레스 없이 만들어 드립니다.",
