      "storyP2": "저희의 약속은 신청 처리에만 그치지 않습니다. 전문적인 안내, 맞춤형 솔루션, 그리고 모든 단계에서의 장기적인 지원을 통해 고객이 자신감을 가지고 말레이시아에서 미래를 설계할 수 있도록 돕습니다.",
