    "faq": {
      "eyebrow": "よくある質問",
      "title": "よくあるご質問",
      "q1": "マレーシア・マイ・セカンドホーム(MM2H)プログラムとは何ですか?",
      "a1": "MM2Hは、マレーシア政府が運営する長期居住プログラムで、外国籍の方が更新可能な許可証でマレーシアに居住できる制度です。カテゴリーにより有効期間は5年から20年まで異なります。退職者、ご家族、投資家、東南アジアでセカンドホームを求めるリモートワーカーの方々に適しています。",
      "q2": "MM2Hの申請資格があるのはどなたですか?",
      "a2": "資格要件は選択するカテゴリーによって異なります。プラチナ、ゴールド、シルバーは主申請者が25歳以上である必要があり、SEZ/SFZカテゴリーは21歳以上が必要です。すべての申請者は、必要な定期預金の証明を提示し、One Stop Centre MM2Hが定める収入・不動産要件を満たす必要があります。",
      "q3": "家族を申請に含めることはできますか?",
      "a3": "はい。法律上の配偶者、35歳以下の未婚の子、両親または配偶者の両親を、同一申請の扶養家族として含めることができます。扶養家族1名ごとに該当する手数料が適用されます。",
      "q4": "MM2Hビザの有効期間はどのくらいですか?",
      "a4": "有効期間はカテゴリーにより異なります:プラチナは20年、ゴールドは15年、シルバーは5年、SEZ/SFZは両区分とも10年です。すべての期間はプログラム条件を継続して満たす限り更新可能です。",
      "q5": "申請に必要な財務要件は何ですか?",
      "a5": "各カテゴリーはマレーシアの銀行への定期預金が必要です:プラチナはUSD 1,000,000、ゴールドはUSD 500,000、シルバーはUSD 150,000、SEZ/SFZは年齢によりUSD 65,000またはUSD 32,000です。プラチナ、ゴールド、シルバーは、定められた最低価格以上の住宅用不動産の購入も義務付けられています。",
      "q6": "MM2Hビザ保持者はマレーシアで不動産を購入できますか?",
      "a6": "はい。プラチナ、ゴールド、シルバーの各カテゴリーは、そのカテゴリーで定められた最低価格以上の住宅用不動産の購入が義務付けられています。SEZ/SFZカテゴリーは、該当する経済特区開発プロジェクトが定める最低価格に従います。",
      "q7": "MM2Hステータス取得後、海外所得は課税対象になりますか?",
      "a7": "現行のプログラム規定では、MM2H定期預金から得られる海外源泉の資金、所得、利益はマレーシアの税金が免除されます。マレーシア国内源泉の所得については、状況により課税対象となる場合があります。",
      "q8": "申請にはどのような書類が必要ですか?",
      "a8": "一般的な必要書類には、有効なパスポート、収入または貯蓄の証明、健康診断書、無犯罪証明書、パスポートサイズの写真が含まれ、扶養家族を含む場合は婚姻証明書と出生証明書も必要です。正確な要件は国籍とカテゴリーによって異なり、すべての書類は必要に応じて適切に翻訳・認証される必要があります。",
      "q9": "MM2Hの申請手続きにはどのくらいの期間がかかりますか?",
      "a9": "処理期間はカテゴリーおよび書類・財務要件の完了スピードによって異なりますが、申請者は通常、初回提出、原則承認、預金の預け入れ、最終ビザ発給という段階を経て数か月を要します。経験豊富なアドバイザーと協力することで、書類不備による遅延を回避できます。",
      "q10": "MM2Hでマレーシアに常時滞在する必要はありますか?",
      "a10": "いいえ。プラチナ、ゴールド、シルバーの各カテゴリーは、主申請者が50歳未満の場合のみ、年間最低90日の滞在が必要です。50歳以上の方には最低滞在日数の要件はありません。SEZ/SFZカテゴリーも同様の年齢別制度に従います。"
    },
