      "storyP1": "マレーシア・マイ・セカンドホーム(MM2H)の主要コンサルタントとして、アジアで最も人気のあるマレーシア居住プログラムの一つを、お客様が自信を持ってスムーズに進められるようサポートしています。より良いライフスタイル、退職後の生活、お子様への質の高い教育、投資機会、長期居住など、どのようなご希望であっても、経験豊富な当社チームがマイ・セカンドホーム・マレーシアの旅路全体を通じて一貫したサポートを提供いたします。",
      "storyP2": "私たちのお約束は、申請手続きの処理だけにとどまりません。専門的なご案内、お客様に合わせたソリューション、そしてあらゆる段階での長期的なサポートを通じて、お客様が自信を持ってマレーシアでの将来を築けるようお手伝いいたします。",
